action.command:
cat > /tmp/cs.php <<'EOF'
<?php
$storage = new \Drupal\Core\Config\FileStorage(\Drupal::root() . '/../config/sync');
$names = $storage->listAll();
$active = \Drupal::configFactory()->listAll();
$onlysync = array_diff($names, $active);
$prefix = [];
foreach ($onlysync as $n) { $p = explode('.', $n)[0]; $prefix[$p] = ($prefix[$p] ?? 0) + 1; }
arsort($prefix);
echo "total only-in-sync: " . count($onlysync) . PHP_EOL;
foreach ($prefix as $p=>$c) echo str_pad($p,40) . $c . PHP_EOL;
EOF
cd /workspace && cp /tmp/cs.php /workspace/cs_tmp.php && su ddevuser -c "ddev drush php:script cs_tmp.php" 2>&1 | tail -40; rm -f /workspace/cs_tmp.php

